 if len(p['cross_sources'])!=6 or {q['key']for q in p['cross_sources']}!=set(CROSS_SOURCE_BINDINGS):raise ValueError('nineteenth quote source scope changed')
 audit=nineteenth_quote_audit(p['cross_sources'],fresh)
 from st_regime_comparison import build
